package com.aurax.operator.operator
object AccessibilityGuardrails { val BLOCKED_PACKAGES=setOf("com.google.android.apps.authenticator2","com.android.settings.security","com.android.settings"); val BLOCKED_NODE_CLASSES=setOf("android.widget.EditText"); val CONFIRM_ACTIONS=setOf("delete","purchase","subscribe","pay","transfer","send","install","uninstall","remove","reset","factory reset"); val SENSITIVE_TERMS=setOf("password","passcode","otp","one-time code","verification code","credit card","card number","cvv","bank account","checkout","payment","pay now","login","sign in","incognito","private browsing"); fun isSensitiveText(text:String)=SENSITIVE_TERMS.any{text.contains(it,true)}; fun requiresConfirmation(action:String)=CONFIRM_ACTIONS.any{action.contains(it,true)} }